def sha_bytes(b): return hashlib.sha256(b).hexdigest()
def sha_json(x): return sha_bytes(json.dumps(x,sort_keys=True,separators=(',',':'),default=str).encode())
def source_sha(): return sha_bytes(SOURCE.read_bytes())

def _load_graph():
    raw=zlib.decompress(base64.b85decode(_GRAPH_PAYLOAD.encode()))
    if sha_bytes(raw)!=GRAPH_PAYLOAD_SHA256: raise RuntimeError('embedded graph payload hash mismatch')
    z=np.load(io.BytesIO(raw),allow_pickle=False)
    return {k:z[k] for k in z.files}
GRAPH=_load_graph()

def interval(vals):
    x=[float(v) for v in vals if v is not None and math.isfinite(float(v))]; n=len(x)
    out={'n':n,'mean':float(np.mean(x)) if x else None,'low':None,'high':None}
    if n>=2:
        sd=float(np.std(x,ddof=1)); crit=float(student_t.ppf(.975,n-1)) if student_t is not None else T95.get(n-1,1.96)
        h=crit*sd/math.sqrt(n); out.update(sd=sd,low=out['mean']-h,high=out['mean']+h)
    return out

def paired(rows,left,right,key,load):
    vals=[]
    seeds=sorted({int(r['seed']) for r in rows if int(r['load'])==int(load)})
    for s in seeds:
        a=next((r for r in rows if int(r['seed'])==s and int(r['load'])==int(load) and r['arm']==left),None)
        b=next((r for r in rows if int(r['seed'])==s and int(r['load'])==int(load) and r['arm']==right),None)
        if a and b and a.get(key) is not None and b.get(key) is not None: vals.append(float(a[key])-float(b[key]))
    return interval(vals)

def atomic_json(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(obj,indent=1,default=str));os.replace(tmp,path)
def atomic_gzip_json(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+'.tmp')
    with gzip.open(tmp,'wt') as f:json.dump(obj,f,default=str,separators=(',',':'))
    os.replace(tmp,path)
def load_gzip_json(path):
    with gzip.open(path,'rt') as f:return json.load(f)
def atomic_pickle(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+'.tmp')
    with open(tmp,'wb') as f:pickle.dump(obj,f,protocol=5)
    os.replace(tmp,path)
def load_pickle(path):
    with open(path,'rb') as f:return pickle.load(f)
def rss_bytes():
    r=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss);return r if sys.platform.startswith('darwin') else r*1024

def softmax(logits):
    x=np.asarray(logits,dtype=np.float64);x=x-np.max(x);p=np.exp(x);return p/max(float(p.sum()),1e-300)
def loss_bits(p,y):return -math.log2(max(float(p[int(y)]),1e-300))

# -----------------------------------------------------------------------------
# Workload (same controlled A→B→C→D structure used in recent rounds)
# -----------------------------------------------------------------------------
def surface_context(key,wrapper):
    w=int(wrapper);k=bytearray(key);m=KEY_XOR_MASKS[w];k[0]^=m[0];k[1]^=m[1]
    c=PREFIX+HEADERS[w]+bytes(k)+SEPARATORS[w]
    if len(c)!=12:raise AssertionError('context length')
    return c

def context_rep(history):
    """96D signed byte representation; partial histories are left-zero-padded."""
    b=bytes(history)[-12:]; out=np.zeros(CONTEXT_D,dtype=np.float64)
    if b:
        a=np.frombuffer(b,dtype=np.uint8);a=BYTE_PERM[a];bits=BIT_CODE[a].ravel();out[-len(bits):]=bits
    n=float(np.linalg.norm(out));return out/n if n>1e-12 else out

def make_stream(seed,load,repeats=REPEATS,smoke=False):
    rr=np.random.default_rng(int(seed)+810007);count=4 if smoke else int(load)//4;reps=2 if smoke else int(repeats);waves=4
    alphabet=np.frombuffer(b'0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ',dtype=np.uint8);keys=[]
    while len(keys)<count*waves:
        k=bytes(rr.choice(alphabet,size=6))
        if k not in keys:keys.append(k)
    labels=rr.choice(np.frombuffer(b'abcdefghijklmnopqrstuvwx',dtype=np.uint8),size=len(keys)).astype(int)
    nrev=max(1,count//4);revised=list(range(nrev));noisy=list(range(nrev,2*nrev));untouched=list(range(2*nrev,count))
    changed={i:int(ord('a')+(int(labels[i])-ord('a')+1+int(rr.integers(23)))%24) for i in revised}
    rows=[];checkpoints=[]
    def add(i,target,kind,exposure,wave,wrapper):
        raw=surface_context(keys[i],wrapper)+bytes([int(target)])+b'\n';assert len(raw)==14
        rows.append({'key_id':int(i),'target':int(target),'kind':kind,'exposure':int(exposure),'wave':wave,'wrapper':int(wrapper),'raw':raw})
    for w in range(waves):
        cohort=chr(65+w);start=w*count;end=(w+1)*count
        for ex in range(1,reps+1):
            for i in rr.permutation(np.arange(start,end)):add(int(i),int(labels[i]),'acquisition',ex,cohort,(ex-1)%2)
            if ex in tuple(x for x in (1,2,4,8) if x<=reps):checkpoints.append({'record_count':len(rows),'name':f'{cohort}_acq_{ex}','type':'acquisition','wave':cohort,'exposure':ex})
        checkpoints.append({'record_count':len(rows),'name':f'after_{cohort}','type':'wave','wave':cohort})
        if w==1:
            for i in noisy:
                wrong=ord('a')+(int(labels[i])-ord('a')+1)%24;add(i,wrong,'one_off_noise',1,cohort,0)
        if w==2:
            for ex in range(1,3 if smoke else 9):
                for i in rr.permutation(revised):add(int(i),changed[int(i)],'revision',ex,cohort,0)
                if ex in (1,2,4,8):checkpoints.append({'record_count':len(rows),'name':f'revision_{ex}','type':'revision','wave':cohort,'exposure':ex})
    raw=b''.join(r['raw'] for r in rows)
    return {'seed':int(seed),'load':int(load),'keys':keys,'labels':labels,'revised':revised,'noisy':noisy,'untouched':untouched,'revisions':changed,'rows':rows,'raw':raw,'checkpoints':checkpoints,'keys_per_wave':count,'repeats':reps,'raw_sha256':sha_bytes(raw)}

# -----------------------------------------------------------------------------
# Raw graph indexing / controls
# -----------------------------------------------------------------------------
# The embedded NPZ stores edge endpoints already mapped to local population indices;
# the uint64 *_ids arrays preserve the raw BANC IDs for provenance.
PK_PRE=np.asarray(GRAPH['pk_pre'],dtype=np.int32); PK_POST=np.asarray(GRAPH['pk_post'],dtype=np.int32); PK_COUNT=np.asarray(GRAPH['pk_count'],dtype=np.float64)
KM_PRE_RAW=np.asarray(GRAPH['km_pre'],dtype=np.int32); KM_POST_RAW=np.asarray(GRAPH['km_post'],dtype=np.int32); KM_COUNT_RAW=np.asarray(GRAPH['km_count'],dtype=np.float64)
MM_PRE_RAW=np.asarray(GRAPH['mm_pre'],dtype=np.int32); MM_POST_RAW=np.asarray(GRAPH['mm_post'],dtype=np.int32); MM_COUNT_RAW=np.asarray(GRAPH['mm_count'],dtype=np.float64)

def degree_rewire_bipartite(pre,post,n_left,n_right,seed,swaps_mult=10):
    rg=np.random.default_rng(int(seed));pre=np.asarray(pre,dtype=np.int32).copy();post=np.asarray(post,dtype=np.int32).copy();E=len(pre);edges={(int(a),int(b)) for a,b in zip(pre,post)}
    target=int(swaps_mult*E);done=tries=0;maxtries=target*40+1000
    while done<target and tries<maxtries:
        tries+=1;i,j=rg.integers(0,E,size=2)
        if i==j:continue
        a,b=int(pre[i]),int(post[i]);c,d=int(pre[j]),int(post[j])
        if a==c or b==d:continue
        if (a,d) in edges or (c,b) in edges:continue
        edges.remove((a,b));edges.remove((c,d));edges.add((a,d));edges.add((c,b));post[i]=d;post[j]=b;done+=1
    if done<target//2:raise RuntimeError(f'rewire incomplete {done}/{target}')
    return pre,post,done

def degree_rewire_directed(pre,post,n,seed,swaps_mult=20):
    # Same double-edge swap, disallow self loops; raw input already excludes self.
    rg=np.random.default_rng(int(seed));pre=np.asarray(pre,dtype=np.int32).copy();post=np.asarray(post,dtype=np.int32).copy();E=len(pre);edges={(int(a),int(b)) for a,b in zip(pre,post)}
    target=int(swaps_mult*E);done=tries=0;maxtries=target*80+1000
    while done<target and tries<maxtries:
        tries+=1;i,j=rg.integers(0,E,size=2)
        if i==j:continue
        a,b=int(pre[i]),int(post[i]);c,d=int(pre[j]),int(post[j])
        if a==c or b==d or a==d or c==b:continue
        if (a,d) in edges or (c,b) in edges:continue
        edges.remove((a,b));edges.remove((c,d));edges.add((a,d));edges.add((c,b));post[i]=d;post[j]=b;done+=1
    if done<target//2:raise RuntimeError(f'directed rewire incomplete {done}/{target}')
    return pre,post,done

def assign_counts_within_post(post,raw_post,raw_count,seed):
    rg=np.random.default_rng(int(seed));out=np.zeros(len(post),dtype=np.float64)
    for j in range(MBON_N):
        vals=np.asarray(raw_count[np.asarray(raw_post)==j],dtype=np.float64).copy();idx=np.flatnonzero(np.asarray(post)==j)
        if len(vals)!=len(idx):raise AssertionError(('column degree mismatch',j,len(vals),len(idx)))
        if len(vals)>1:vals=vals[rg.permutation(len(vals))]
        out[idx]=vals
    return out

def scales_from_counts(post,count,binary=False):
    if binary:return np.ones(len(post),dtype=np.float64)
    out=np.zeros(len(post),dtype=np.float64)
    for j in range(MBON_N):
        idx=np.flatnonzero(np.asarray(post)==j)
        if len(idx):
            vals=np.asarray(count[idx],dtype=np.float64);den=math.sqrt(max(float(np.mean(vals)),1e-12));out[idx]=np.sqrt(vals)/den
    return out

def arm_graphs(seed):
    rg=np.random.default_rng(int(seed)+490031)
    # raw
    raw=(KM_PRE_RAW.copy(),KM_POST_RAW.copy(),KM_COUNT_RAW.copy())
    # KC row permutation: M'[i,j]=M[pi(i),j], so old row r moves to inv_pi[r]
    pi=rg.permutation(KC_N);inv=np.empty(KC_N,dtype=np.int32);inv[pi]=np.arange(KC_N,dtype=np.int32)
    kid=(inv[KM_PRE_RAW],KM_POST_RAW.copy(),KM_COUNT_RAW.copy())
    # degree-preserving support; keep each MBON incoming count multiset
    rp,rq,swaps=degree_rewire_bipartite(KM_PRE_RAW,KM_POST_RAW,KC_N,MBON_N,int(seed)+490032,10)
    rc=assign_counts_within_post(rq,KM_POST_RAW,KM_COUNT_RAW,int(seed)+490033);rew=(rp,rq,rc)
    # weight shuffle on exact support
    wc=assign_counts_within_post(KM_POST_RAW,KM_POST_RAW,KM_COUNT_RAW,int(seed)+490034);wsh=(KM_PRE_RAW.copy(),KM_POST_RAW.copy(),wc)
    binar=(KM_PRE_RAW.copy(),KM_POST_RAW.copy(),np.ones_like(KM_COUNT_RAW))
    return {'RAW-ALIGNED':raw,'KC-ID-SHUFFLE':kid,'KM-DEGREE-REWIRE':rew,'KM-WEIGHT-SHUFFLE':wsh,'KM-BINARY':binar}, {'rewire_swaps':int(swaps),'kc_perm_sha':sha_bytes(pi.tobytes())}

def graph_degree_audit(pre,post,count):
    return {'edges':int(len(pre)),'count_sum':float(np.sum(count)),'kc_out_degree_sha':sha_bytes(np.bincount(pre,minlength=KC_N).astype(np.int32).tobytes()),'kc_out_degree_multiset_sha':sha_bytes(np.sort(np.bincount(pre,minlength=KC_N)).astype(np.int32).tobytes()),'mbon_in_degree_sha':sha_bytes(np.bincount(post,minlength=MBON_N).astype(np.int32).tobytes()),'count_multiset_sha':sha_bytes(np.sort(np.asarray(count,dtype=np.float64)).tobytes())}

# -----------------------------------------------------------------------------
# Sensory encoder / codebook
# -----------------------------------------------------------------------------
class SensoryCore:
    def __init__(self,seed):
        self.seed=int(seed);rg=np.random.default_rng(self.seed+490001)
        self.ad_idx=np.stack([rg.choice(CONTEXT_D,ADAPTOR_CONTACTS,replace=False) for _ in range(PN_N)]).astype(np.int16)
        self.ad_sign=(2*rg.integers(0,2,size=(PN_N,ADAPTOR_CONTACTS))-1).astype(np.float64)/math.sqrt(ADAPTOR_CONTACTS)
        # normalized raw PN->KC scale by KC incoming count sum
        denom=np.bincount(PK_POST,weights=PK_COUNT,minlength=KC_N);self.pk_scale=np.sqrt(PK_COUNT)/np.sqrt(np.maximum(denom[PK_POST],1e-12))
        self._cache=collections.OrderedDict();self.cache_cap=8192
        crg=np.random.default_rng(self.seed+490002);C=(2*crg.integers(0,2,size=(OUTPUTS,MBON_N))-1).astype(np.float64);C/=np.linalg.norm(C,axis=1,keepdims=True);self.codebook=C
    def clear_transient(self):self._cache.clear()
    def kc(self,history):
        b=bytes(history)[-12:]
        if b in self._cache:
            q=self._cache.pop(b);self._cache[b]=q;ix,v=q;z=np.zeros(KC_N,dtype=np.float64);z[ix]=v;return z
        x=context_rep(b);pn=np.tanh(np.einsum('pc,pc->p',x[self.ad_idx],self.ad_sign,optimize=True))
        val=self.pk_scale*pn[PK_PRE];drive=np.bincount(PK_POST,weights=val,minlength=KC_N);act=np.tanh(drive)
        ix=np.argpartition(-np.abs(act),KC_ACTIVE-1)[:KC_ACTIVE];ix=np.sort(ix);v=act[ix];n=float(np.linalg.norm(v));v=v/max(n,1e-12)
        self._cache[b]=(ix.astype(np.int16),v.astype(np.float64))
        if len(self._cache)>self.cache_cap:self._cache.popitem(last=False)
        z=np.zeros(KC_N,dtype=np.float64);z[ix]=v;return z
    def audit(self):
        cos=self.codebook@self.codebook.T;mask=~np.eye(OUTPUTS,dtype=bool)
        return {'rank':int(np.linalg.matrix_rank(self.codebook)),'max_abs_pair_cosine':float(np.max(np.abs(cos[mask]))),'mean_abs_pair_cosine':float(np.mean(np.abs(cos[mask]))),'adaptor_sha':sha_bytes(self.ad_idx.tobytes()+self.ad_sign.tobytes()),'codebook_sha':sha_bytes(self.codebook.tobytes())}

# -----------------------------------------------------------------------------
# Sparse KC->MBON arms
# -----------------------------------------------------------------------------
class KMArm:
    def __init__(self,name,pre,post,count):
        self.name=name;self.pre=np.asarray(pre,dtype=np.int32);self.post=np.asarray(post,dtype=np.int16);self.count=np.asarray(count,dtype=np.float64)
        self.scale=scales_from_counts(self.post,self.count,binary=(name=='KM-BINARY'));self.theta=np.zeros(len(self.pre),dtype=np.float64);self.updates=0;self.update_norm_sq=0.
    def ff(self,z):
        w=self.scale*self.theta*z[self.pre];return np.bincount(self.post,weights=w,minlength=MBON_N)
    def probs_from_h(self,h,C):return softmax((C@h)/TAU)
    def predict(self,z,C):
        h=self.ff(z);return self.probs_from_h(h,C),h
    def update(self,z,y,C,p=None):
        if p is None:p,_=self.predict(z,C)
        expected=p@C;e=RESIDUAL_SCALE*(C[int(y)]-expected);delta=ETA*self.scale*z[self.pre]*e[self.post]
        self.theta+=delta;self.updates+=1;self.update_norm_sq+=float(delta@delta);return float(np.linalg.norm(delta))
    def learned_bytes(self):return int(self.theta.nbytes)
    def state_hash(self):return sha_bytes(self.theta.tobytes()+str(self.updates).encode())

class BlockAModel:
    def __init__(self,seed):
        self.seed=int(seed);self.sensory=SensoryCore(seed);gs,self.control_audit=arm_graphs(seed);self.arms={a:KMArm(a,*gs[a]) for a in A_ARMS}
    def clear_transient(self):self.sensory.clear_transient()
    def predict_all(self,history):
        z=self.sensory.kc(history);return z,{a:self.arms[a].predict(z,self.sensory.codebook) for a in A_ARMS}
    def update_all(self,z,y,preds):
        return {a:self.arms[a].update(z,y,self.sensory.codebook,preds[a][0]) for a in A_ARMS}
    def state_hash(self):
        h=hashlib.sha256();
        for a in A_ARMS:h.update(self.arms[a].theta.tobytes());h.update(str(self.arms[a].updates).encode())
        return h.hexdigest()

# -----------------------------------------------------------------------------
# Block B recurrence
# -----------------------------------------------------------------------------
def spectral_normalize(M,target=REC_RADIUS):
    eig=np.linalg.eigvals(M);rho=float(np.max(np.abs(eig))) if len(eig) else 0.
    return M*(target/rho) if rho>1e-12 else M, rho

def recurrence_graphs(seed):
    def build(pre,post,count):
        M=np.zeros((MBON_N,MBON_N),dtype=np.float64);vals=np.sqrt(np.asarray(count,dtype=np.float64));M[np.asarray(post,dtype=int),np.asarray(pre,dtype=int)]=vals;np.fill_diagonal(M,0.);M,rho=spectral_normalize(M);return M,rho
    rawM,rawrho=build(MM_PRE_RAW,MM_POST_RAW,MM_COUNT_RAW)
    rp,rq,swaps=degree_rewire_directed(MM_PRE_RAW,MM_POST_RAW,MBON_N,int(seed)+490041,20);rc=assign_counts_within_post(rq,MM_POST_RAW,MM_COUNT_RAW,int(seed)+490042);rewM,rewrho=build(rp,rq,rc)
    wc=assign_counts_within_post(MM_POST_RAW,MM_POST_RAW,MM_COUNT_RAW,int(seed)+490043);shM,shrho=build(MM_PRE_RAW,MM_POST_RAW,wc)
    zero=np.zeros((MBON_N,MBON_N),dtype=np.float64)
    return {'RAW-KM-FF':zero,'RAW-KM+RAW-MM':rawM,'RAW-KM+MM-DEGREE-REWIRE':rewM,'RAW-KM+MM-WEIGHT-SHUFFLE':shM}, {'rewire_swaps':int(swaps),'raw_pre_rho':rawrho,'rewire_pre_rho':rewrho,'shuffle_pre_rho':shrho}

class BlockBModel:
    def __init__(self,seed):
        self.seed=int(seed);self.sensory=SensoryCore(seed);R,self.rec_audit=recurrence_graphs(seed);self.R=R
        self.arms={a:KMArm(a,KM_PRE_RAW,KM_POST_RAW,KM_COUNT_RAW) for a in B_ARMS};self.h={a:np.zeros(MBON_N,dtype=np.float64) for a in B_ARMS}
        self.state_stats={a:{'n':0,'sum_norm':0.,'sat_events':0,'ff_sum_norm':0.,'rec_sum_norm':0.} for a in B_ARMS}
    def clear_transient(self):self.sensory.clear_transient()
    def step_predict(self,history):
        z=self.sensory.kc(history);out={}
        for a in B_ARMS:
            ff=self.arms[a].ff(z);rec=self.R[a]@self.h[a];h=ff+rec;self.h[a]=h
            st=self.state_stats[a];st['n']+=1;st['sum_norm']+=float(np.linalg.norm(h));st['ff_sum_norm']+=float(np.linalg.norm(ff));st['rec_sum_norm']+=float(np.linalg.norm(rec));st['sat_events']+=int(float(np.mean(np.abs(h)>20.))>.95)
            out[a]=(self.arms[a].probs_from_h(h,self.sensory.codebook),h,ff,rec)
        return z,out
    def update_all(self,z,y,preds):return {a:self.arms[a].update(z,y,self.sensory.codebook,preds[a][0]) for a in B_ARMS}
    def isolated_prob(self,arm,context):
        hist=bytearray();h=np.zeros(MBON_N,dtype=np.float64)
        for bb in bytes(context):
            z=self.sensory.kc(hist);ff=self.arms[arm].ff(z);h=ff+self.R[arm]@h;hist.append(int(bb));
            if len(hist)>12:del hist[0]
        z=self.sensory.kc(hist);ff=self.arms[arm].ff(z);h=ff+self.R[arm]@h;return self.arms[arm].probs_from_h(h,self.sensory.codebook),h
    def state_hash(self):
        h=hashlib.sha256()
        for a in B_ARMS:h.update(self.arms[a].theta.tobytes());h.update(self.h[a].tobytes());h.update(str(self.arms[a].updates).encode())
        return h.hexdigest()

@dataclass
class Agg:
    n:int=0;loss:float=0.;correct:int=0
    def add(self,p,y):self.n+=1;self.loss+=loss_bits(p,y);self.correct+=int(int(np.argmax(p))==int(y))
    def result(self):return {'n':self.n,'bpb':self.loss/self.n if self.n else None,'accuracy':self.correct/self.n if self.n else None}

# -----------------------------------------------------------------------------
# Probes / interference
# -----------------------------------------------------------------------------
def current_target(stream,current_targets,i):return int(current_targets[int(i)])
def probe_contexts(stream,ids,wrappers,current_targets):
    return [(surface_context(stream['keys'][i],w),current_target(stream,current_targets,i),int(i),int(w)) for i in ids for w in wrappers]

def probe_A(model,stream,current_targets,ids,wrappers=(4,5)):
    ctx=probe_contexts(stream,ids,wrappers,current_targets);out={a:Agg() for a in A_ARMS}
    for c,y,_,_ in ctx:
        z=model.sensory.kc(c)
        for a in A_ARMS:p,_=model.arms[a].predict(z,model.sensory.codebook);out[a].add(p,y)
    return {a:g.result() for a,g in out.items()}

def probe_B(model,stream,current_targets,ids,wrappers=(4,5)):
    ctx=probe_contexts(stream,ids,wrappers,current_targets);out={a:Agg() for a in B_ARMS}
    for c,y,_,_ in ctx:
        for a in B_ARMS:p,_=model.isolated_prob(a,c);out[a].add(p,y)
    return {a:g.result() for a,g in out.items()}

def probe_checkpoint(model,block,stream,current_targets,cp):
    wi=ord(cp['wave'])-65;count=stream['keys_per_wave'];rows=[];probe=probe_A if block=='A' else probe_B;arms=A_ARMS if block=='A' else B_ARMS
    for cohort in range(wi+1):
        ids=list(range(cohort*count,min((cohort+1)*count,len(stream['keys']))));tr=probe(model,stream,current_targets,ids,(0,1));he=probe(model,stream,current_targets,ids,(4,5))
        for a in arms:rows.append({'checkpoint':cp['name'],'wave':cp['wave'],'cohort':chr(65+cohort),'arm':a,'trained_accuracy':tr[a]['accuracy'],'trained_bpb':tr[a]['bpb'],'heldout_accuracy':he[a]['accuracy'],'heldout_bpb':he[a]['bpb']})
    return rows

def sample_interference_records(stream,seed,maximum=INTERFERENCE_MAX):
    inds=[i for i,r in enumerate(stream['rows']) if r['kind']=='acquisition' and r['wave'] in ('B','C','D')]
    rg=np.random.default_rng(int(seed)+490061);chosen=rg.choice(inds,size=min(maximum,len(inds)),replace=False);return set(map(int,chosen))

def interference_probe_set(stream,current_targets,row,seed,maximum=INTERFERENCE_PROBES):
    cid=int(row['key_id']);y=int(row['target']);allids=list(range(len(stream['keys'])));sameout=[i for i in allids if i!=cid and int(current_targets[i])==y];diff=[i for i in allids if i!=cid and int(current_targets[i])!=y]
    rg=np.random.default_rng(int(seed)*1000003+cid*9176+int(row['exposure'])*71+ord(row['wave']))
    out=[(surface_context(stream['keys'][cid],4),y,cid,'same_identity_alt')]
    for cat,pool,n in [('same_outcome_diff_identity',sameout,max(1,maximum//4)),('different_outcome_diff_identity',diff,max(1,maximum//2))]:
        if pool:
            take=rg.choice(pool,size=min(n,len(pool)),replace=False)
            for i in take:out.append((surface_context(stream['keys'][int(i)],4),int(current_targets[int(i)]),int(i),cat))
    return out

def interference_losses_A(model,probes):
    out={a:[] for a in A_ARMS}
    for c,y,_,_ in probes:
        z=model.sensory.kc(c)
        for a in A_ARMS:p,_=model.arms[a].predict(z,model.sensory.codebook);out[a].append(loss_bits(p,y))
    return out

def interference_losses_B(model,probes):
    out={a:[] for a in B_ARMS}
    for c,y,_,_ in probes:
        for a in B_ARMS:p,_=model.isolated_prob(a,c);out[a].append(loss_bits(p,y))
    return out

def interference_rows(probes,before,after,arms,event_index,row):
    rows=[]
    for a in arms:
        groups=collections.defaultdict(list)
        for j,(_,_,_,cat) in enumerate(probes):groups[cat].append(float(after[a][j]-before[a][j]));groups['all'].append(float(after[a][j]-before[a][j]))
        for cat,vals in groups.items():rows.append({'event_index':int(event_index),'arm':a,'category':cat,'n_probes':len(vals),'mean_delta_bpb':float(np.mean(vals)) if vals else None,'wave':row['wave'],'kind':row['kind'],'key_id':int(row['key_id']),'outcome':int(row['target'])})
    return rows

def kc_geometry(sensory,stream,maximum=48):
    count=stream['keys_per_wave'];ids=list(range(min(count,maximum)));same=[];diff_same=[];diff_diff=[]
    zs={(i,w):sensory.kc(surface_context(stream['keys'][i],w)) for i in ids for w in (0,1,4)}
    for i in ids:same.append(float(zs[(i,0)]@zs[(i,4)]))
    for i in ids:
        for j in ids:
            if i==j:continue
            v=float(zs[(i,0)]@zs[(j,0)])
            if int(stream['labels'][i])==int(stream['labels'][j]):diff_same.append(v)
            else:diff_diff.append(v)
    return {'same_identity':float(np.mean(same)) if same else None,'diff_same_outcome':float(np.mean(diff_same)) if diff_same else None,'diff_diff_outcome':float(np.mean(diff_diff)) if diff_diff else None}

def mbon_geometry_B(model,stream,maximum=32):
    ids=list(range(min(stream['keys_per_wave'],maximum)));rows=[]
    for a in B_ARMS:
        hs={(i,w):model.isolated_prob(a,surface_context(stream['keys'][i],w))[1] for i in ids for w in (0,4)}
        def cos(u,v):
            nu=float(np.linalg.norm(u));nv=float(np.linalg.norm(v));return float(u@v/max(nu*nv,1e-12))
        same=[cos(hs[(i,0)],hs[(i,4)]) for i in ids];diff=[cos(hs[(i,0)],hs[(j,0)]) for i in ids for j in ids if i!=j]
        rows.append({'arm':a,'same_identity_cos':float(np.mean(same)) if same else None,'different_identity_cos':float(np.mean(diff)) if diff else None})
    return rows

# -----------------------------------------------------------------------------
# Runtime/checkpoint
# -----------------------------------------------------------------------------
@dataclass
class RuntimeA:
    record_index:int;event_index:int;history:bytearray;current_targets:np.ndarray;model:BlockAModel;groups:dict;checkpoints:list=field(default_factory=list);interference:list=field(default_factory=list);update_norms:dict=field(default_factory=dict);peak_rss:int=0
@dataclass
class RuntimeB:
    record_index:int;event_index:int;history:bytearray;current_targets:np.ndarray;model:BlockBModel;groups:dict;checkpoints:list=field(default_factory=list);interference:list=field(default_factory=list);update_norms:dict=field(default_factory=dict);peak_rss:int=0

def new_runtime(seed,stream,block):
    arms=A_ARMS if block=='A' else B_ARMS;M=BlockAModel(seed) if block=='A' else BlockBModel(seed);G={a:{'whole':Agg(),'target':Agg(),'nontarget':Agg()} for a in arms};U={a:0. for a in arms}
    cls=RuntimeA if block=='A' else RuntimeB;return cls(0,0,bytearray(),np.array(stream['labels'],dtype=np.int64),M,G,[],[],U,rss_bytes())

def clear_transient(st):st.model.clear_transient()
def runtime_hash(st):return sha_bytes((st.model.state_hash()+sha_bytes(bytes(st.history))+sha_bytes(st.current_targets.tobytes())+str(st.record_index)+':'+str(st.event_index)).encode())

def job_identity(seed,load,block,stream_sha,smoke):return sha_json({'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,'graph':GRAPH_PAYLOAD_SHA256,'seed':int(seed),'load':int(load),'block':block,'stream':stream_sha,'smoke':bool(smoke),'eta':ETA,'tau':TAU,'radius':REC_RADIUS})

def save_checkpoint(path,identity,st):clear_transient(st);atomic_pickle(path,{'identity':identity,'state':st})
def load_checkpoint(path,identity):
    obj=load_pickle(path)
    if obj.get('identity')!=identity:raise RuntimeError('checkpoint identity mismatch')
    return obj['state']

def run_job(seed,load,block,out_dir,smoke=False,stop_after_records=None):
    out_dir=Path(out_dir);jobs=out_dir/'jobs';ckdir=out_dir/'checkpoints';jobs.mkdir(parents=True,exist_ok=True);ckdir.mkdir(parents=True,exist_ok=True)
    path=jobs/f'{block}_L{load}_S{seed}.json.gz';stream=make_stream(seed,load,smoke=smoke);ident=job_identity(seed,load,block,stream['raw_sha256'],smoke)
    if path.exists():
        try:
            old=load_gzip_json(path)
            if old.get('identity')==ident:return old['result']
        except Exception:pass
    ck=ckdir/f'{block}_L{load}_S{seed}.pkl';st=load_checkpoint(ck,ident) if ck.exists() else new_runtime(seed,stream,block)
    sampled=sample_interference_records(stream,seed);cpmap=collections.defaultdict(list)
    for cp in stream['checkpoints']:cpmap[int(cp['record_count'])].append(cp)
    arms=A_ARMS if block=='A' else B_ARMS;start=time.perf_counter();records_done=0
    for ri in range(st.record_index,len(stream['rows'])):
        row=stream['rows'][ri]
        for pos,y in enumerate(row['raw']):
            y=int(y)
            if block=='A':z,preds=st.model.predict_all(st.history)
            else:z,preds=st.model.step_predict(st.history)
            for a in arms:st.groups[a]['whole'].add(preds[a][0],y);st.groups[a]['target' if pos==12 else 'nontarget'].add(preds[a][0],y)
            do_audit=(ri in sampled and pos==12 and row['kind']=='acquisition')
            probes=before=None
            if do_audit:
                probes=interference_probe_set(stream,st.current_targets,row,seed);before=interference_losses_A(st.model,probes) if block=='A' else interference_losses_B(st.model,probes)
            norms=st.model.update_all(z,y,preds)
            for a,v in norms.items():st.update_norms[a]+=float(v)
            if do_audit:
                after=interference_losses_A(st.model,probes) if block=='A' else interference_losses_B(st.model,probes);st.interference.extend(interference_rows(probes,before,after,arms,st.event_index,row))
            st.history.append(y)
            if len(st.history)>12:del st.history[0]
            st.event_index+=1
        if row['kind']=='revision':st.current_targets[int(row['key_id'])]=int(row['target'])
        st.record_index=ri+1;records_done+=1;st.peak_rss=max(st.peak_rss,rss_bytes())
