def write_csv(path,rows):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    keys=[]
    for r in rows:
        for k in r:
            if k not in keys:keys.append(k)
    with open(path,'w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=keys);w.writeheader()
        for r in rows:w.writerow(r)

def collect_results(out_dir):
    out=[]
    for p in sorted((Path(out_dir)/'jobs').glob('*.json.gz')):
        try:out.append(load_gzip_json(p)['result'])
        except Exception:pass
    return out

def checkpoint_metric(results,block,checkpoint,cohort,arm,key):
    vals=[]
    for r in results:
        if r['block']!=block:continue
        q=next((x for x in r['checkpoints'] if x['checkpoint']==checkpoint and x['cohort']==cohort and x['arm']==arm),None)
        if q and q.get(key) is not None:vals.append({'seed':r['seed'],'load':r['load'],'value':q[key]})
    return vals

def flatten_terminal(results):
    rows=[]
    for r in results:
        for a,v in r['terminal'].items():rows.append({'seed':r['seed'],'load':r['load'],'block':r['block'],'arm':a,**v,'wall_seconds':r['wall_seconds'],'peak_rss':r['peak_rss']})
    return rows

def flatten_checkpoints(results):
    rows=[]
    for r in results:
        for x in r['checkpoints']:rows.append({'seed':r['seed'],'load':r['load'],'block':r['block'],**x})
    return rows

def flatten_interference(results):
    rows=[]
    for r in results:
        for x in r['interference']:rows.append({'seed':r['seed'],'load':r['load'],'block':r['block'],**x})
    return rows

def interference_summary(irows):
    rows=[]
    for block in ('A','B'):
        arms=A_ARMS if block=='A' else B_ARMS
        for load in sorted({int(x['load']) for x in irows if x['block']==block}):
            for a in arms:
                for cat in ('same_identity_alt','same_outcome_diff_identity','different_outcome_diff_identity','all'):
                    per=[]
                    for s in SCIENCE_SEEDS:
                        vals=[float(x['mean_delta_bpb']) for x in irows if x['block']==block and int(x['load'])==load and int(x['seed'])==s and x['arm']==a and x['category']==cat and x['mean_delta_bpb'] is not None]
                        if vals:per.append(float(np.mean(vals)))
                    q=interval(per);rows.append({'block':block,'load':load,'arm':a,'category':cat,**q})
    return rows

def per_seed_metric_from_cp(cprows,block,load,arm,checkpoint,cohort,key):
    out={}
    for s in SCIENCE_SEEDS:
        q=next((x for x in cprows if x['block']==block and int(x['load'])==load and int(x['seed'])==s and x['arm']==arm and x['checkpoint']==checkpoint and x['cohort']==cohort),None)
        if q and q.get(key) is not None:out[s]=float(q[key])
    return out

def cp_paired(cprows,block,load,left,right,checkpoint,cohort,key):
    a=per_seed_metric_from_cp(cprows,block,load,left,checkpoint,cohort,key);b=per_seed_metric_from_cp(cprows,block,load,right,checkpoint,cohort,key);return interval([a[s]-b[s] for s in sorted(set(a)&set(b))])

def int_paired(isum,block,load,left,right,category):
    # interference_summary lacks per-seed; reconstruct from raw rows in aggregate caller instead.
    return None

