def static_self_test():
    checks={}
    checks['graph_payload_hash']=GRAPH_PAYLOAD_SHA256
    assert len(GRAPH['pn_ids'])==PN_N and len(GRAPH['kc_ids'])==KC_N and len(GRAPH['mbon_ids'])==MBON_N
    assert len(PK_PRE)==22417 and int(PK_COUNT.sum())==168315
    assert len(KM_PRE_RAW)==15523 and int(KM_COUNT_RAW.sum())==28415
    assert len(MM_PRE_RAW)==1141 and int(MM_COUNT_RAW.sum())==10140
    checks['raw_counts']=True
    s=SensoryCore(49971);a=s.audit();assert a['rank']==104
    z=s.kc(surface_context(b'ABC123',0));assert int(np.count_nonzero(z))==KC_ACTIVE and abs(np.linalg.norm(z)-1)<1e-9
    checks['codebook']=a;checks['kc_active']=int(np.count_nonzero(z))
    gs,ca=arm_graphs(49971);rawdeg=graph_degree_audit(*gs['RAW-ALIGNED']);kiddeg=graph_degree_audit(*gs['KC-ID-SHUFFLE']);rewdeg=graph_degree_audit(*gs['KM-DEGREE-REWIRE']);wshdeg=graph_degree_audit(*gs['KM-WEIGHT-SHUFFLE'])
    assert rawdeg['mbon_in_degree_sha']==kiddeg['mbon_in_degree_sha']==rewdeg['mbon_in_degree_sha']==wshdeg['mbon_in_degree_sha']
    # KC-ID-SHUFFLE preserves the row-degree multiset but deliberately reassigns rows to different KC identities.
    assert rawdeg['kc_out_degree_multiset_sha']==kiddeg['kc_out_degree_multiset_sha']
    assert rawdeg['kc_out_degree_sha']==rewdeg['kc_out_degree_sha']==wshdeg['kc_out_degree_sha']
    assert rawdeg['count_multiset_sha']==kiddeg['count_multiset_sha']==rewdeg['count_multiset_sha']==wshdeg['count_multiset_sha']
    checks['A_controls']=True;checks['A_control_audit']=ca
    R,ra=recurrence_graphs(49971)
    for nm,M in R.items():
        if nm=='RAW-KM-FF':continue
        rho=float(np.max(np.abs(np.linalg.eigvals(M))));assert abs(rho-REC_RADIUS)<1e-6,(nm,rho)
    checks['B_controls']=ra
    # one write changes only existing theta and stays finite
    m=BlockAModel(49971);zz=m.sensory.kc(surface_context(b'ABC123',0));pred={a:m.arms[a].predict(zz,m.sensory.codebook) for a in A_ARMS};m.update_all(zz,ord('a'),pred);assert all(np.isfinite(x.theta).all() and x.updates==1 for x in m.arms.values())
    checks['local_write']=True
    return checks

def run_parallel(tasks,workers):
    if int(workers)<=1:return [worker(t) for t in tasks]
    ctx=mp.get_context('spawn');out=[]
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers),mp_context=ctx) as ex:
        futs=[ex.submit(worker,t) for t in tasks]
        for f in concurrent.futures.as_completed(futs):out.append(f.result())
    return out

def engineering_check(out_dir,workers=2):
    out_dir=Path(out_dir);shutil.rmtree(out_dir,ignore_errors=True);out_dir.mkdir(parents=True,exist_ok=True);seed=ENGINEERING_SEEDS[0]
    # forced stop/resume A
    try:run_job(seed,64,'A',out_dir,smoke=True,stop_after_records=3)
    except KeyboardInterrupt:pass
    r1=run_job(seed,64,'A',out_dir,smoke=True);h1=r1['state_hash']
    # clean deterministic rerun in sibling
    other=out_dir.parent/(out_dir.name+'_clean');shutil.rmtree(other,ignore_errors=True);other.mkdir(parents=True,exist_ok=True);r2=run_job(seed,64,'A',other,smoke=True);assert h1==r2['state_hash'],'resume mismatch';shutil.rmtree(other,ignore_errors=True)
    # spawn both blocks
    tasks=[{'seed':ENGINEERING_SEEDS[1],'load':64,'block':'A','out_dir':out_dir,'smoke':True},{'seed':ENGINEERING_SEEDS[1],'load':64,'block':'B','out_dir':out_dir,'smoke':True}]
    run_parallel(tasks,min(2,int(workers)))
    return {'resume_equivalent':True,'spawn_smoke':True,'jobs':len(collect_results(out_dir))}

def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter);ap.add_argument('--out-dir',type=Path,default=Path('v49_results'));ap.add_argument('--stage',choices=('A','B','all','aggregate'),default='all');ap.add_argument('--workers',type=int,default=4);ap.add_argument('--self-test',action='store_true');ap.add_argument('--engineering-check',action='store_true');ap.add_argument('--smoke',action='store_true');ap.add_argument('--seeds',type=int);ap.add_argument('--loads',type=str);ap.add_argument('--max-new-jobs',type=int)
    args=ap.parse_args(argv)
    if args.self_test:print(json.dumps(static_self_test(),indent=2,default=str));return 0
    if args.engineering_check:print(json.dumps(engineering_check(args.out_dir,args.workers),indent=2));return 0
    out=args.out_dir;out.mkdir(parents=True,exist_ok=True)
    seeds=list(SCIENCE_SEEDS[:args.seeds] if args.seeds else SCIENCE_SEEDS);loads=[int(x) for x in args.loads.split(',')] if args.loads else [PRIMARY_LOAD,SECONDARY_LOAD]
    if args.smoke:seeds=list(ENGINEERING_SEEDS);loads=[64]
    if args.stage=='aggregate':
        g=aggregate(out,seeds if args.seeds else SCIENCE_SEEDS,stage='aggregate');print(json.dumps({'A':g['A'].get('verdict'),'B':g['B'].get('verdict'),'upload':str(out/'v49_results_upload.zip')},indent=2));return 0
    def tasks_for(block):
        tasks=[];existing=collect_results(out);done={(r['block'],int(r['load']),int(r['seed'])) for r in existing}
        for L in loads:
            for s in seeds:
                if (block,L,s) not in done:tasks.append({'seed':s,'load':L,'block':block,'out_dir':out,'smoke':args.smoke})
        if args.max_new_jobs is not None:tasks=tasks[:int(args.max_new_jobs)]
        return tasks
    if args.stage in ('A','all'):
        ta=tasks_for('A');print(f'V49 Block A: {len(ta)} new jobs; {len(seeds)} seeds x {len(loads)} loads',flush=True);run_parallel(ta,args.workers)
        ga=aggregate(out,seeds if args.seeds else SCIENCE_SEEDS,stage='A' if args.stage=='A' else 'all');print('Block A verdict:',ga['A'].get('verdict'),flush=True)
        if args.stage=='all' and ga['A'].get('G1',{}).get('pass') is not True:
            print('Block B skipped: RAW-ALIGNED acquisition validity not established.',flush=True);return 0
    if args.stage in ('B','all'):
        # Require Block-A primary acquisition validity when using science/default run.
        if args.stage=='B':
            ga=aggregate(out,seeds if args.seeds else SCIENCE_SEEDS,stage='B-precheck')
            if ga['A'].get('G1',{}).get('pass') is not True:raise SystemExit('Block B requires valid Block-A primary acquisition results.')
        tb=tasks_for('B');print(f'V49 Block B: {len(tb)} new jobs',flush=True);run_parallel(tb,args.workers);g=aggregate(out,seeds if args.seeds else SCIENCE_SEEDS,stage=args.stage);print('Block B verdict:',g['B'].get('verdict'),flush=True)
    print('Wrote',out.resolve());print('Upload',out/'v49_results_upload.zip');return 0

if __name__=='__main__':raise SystemExit(main())
